import{_ as i,o as e,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Crimson/SeaStore 2021-06-09","description":"","frontmatter":{"title":"Ceph Crimson/SeaStore 2021-06-09","date":"2021-06-09T00:00:00.000Z","updated":"2021-06-10T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可伸缩性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Crimson_SeaStore_2021-06-09.md","filePath":"posts/2021/Ceph_Crimson_SeaStore_2021-06-09.md","lastUpdated":1780459816000}'),r={name:"posts/2021/Ceph_Crimson_SeaStore_2021-06-09.md"};function p(s,l,a,n,_,S){return e(),t("div",null,[...l[0]||(l[0]=[o("<p>本次会议主要讨论了Ceph存储系统中的一些关键问题和后续行动计划：</p><ol><li><p><strong>SPDK 和 F2FS 的实现研究</strong>：</p><ul><li>会议讨论了SPDK和F2FS的实现，特别是首次过期处理。</li><li>下一步计划研究LBA实现和段清理器，以提高计算机收集效率。</li><li>讨论了添加序列ID的可能性，以跟踪每次写入的顺序。</li></ul></li><li><p><strong>C-Store 的稳定性问题</strong>：</p><ul><li>C-Store目前存在崩溃问题，仅能完成两次I/O操作。</li><li>建议先观察崩溃情况，再尝试修复，但目前不建议在此部分工作，因为正在添加可中断的未来部分。</li></ul></li><li><p><strong>垃圾收集技术研究</strong>：</p><ul><li>讨论了使用模拟（mocks）来模拟系统行为的可能性，但认为这可能不是最有效的方法。</li><li>建议先观察C-Store的实际行为，再制定段清理器的策略。</li></ul></li><li><p><strong>中断可处理的未来部分</strong>：</p><ul><li>正在添加中断可处理的未来部分，这是一个重大的重构工作。</li><li>建议在完成这部分工作后再进行其他改进。</li></ul></li><li><p><strong>其他技术细节</strong>：</p><ul><li>讨论了使用FIO工具来测试事务管理器的稳定性。</li><li>提到了Zweihan正在添加的长期段垃圾收集机制。</li></ul></li></ol><p>会议决定事项包括：</p><ul><li>继续观察和研究C-Store的崩溃问题，等待中断可处理的未来部分完成后，再进行进一步的改进。</li><li>使用FIO工具来测试和观察C-Store的行为。</li><li>等待Zweihan完成长期段垃圾收集机制的添加，再进行更有效的段清理策略。</li></ul><p>后续行动计划：</p><ul><li>继续研究SPDK和F2FS的实现，特别是LBA和段清理器的部分。</li><li>观察和记录C-Store的崩溃行为，尝试找出根本原因。</li><li>使用FIO工具进行测试，收集C-Store的实际行为数据。</li><li>等待中断可处理的未来部分完成后，再进行C-Store的进一步改进。</li><li>与Zweihan沟通，了解长期段垃圾收集机制的进展。</li></ul><p>会议还讨论了编译器版本问题，建议在GCC 10上进行测试和调试。欢迎新成员加入，期待下次会议能有更多贡献。</p>",7)])])}const d=i(r,[["render",p]]);export{u as __pageData,d as default};
